import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.DYAmjhAm.js";const p=JSON.parse('{"title":"What is Breeze?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-breeze.md","filePath":"guide/what-is-breeze.md","lastUpdated":1789760288000}'),n={name:"guide/what-is-breeze.md"};function o(d,e,s,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-breeze" tabindex="-1">What is Breeze? <a class="header-anchor" href="#what-is-breeze" aria-label="Permalink to &quot;What is Breeze?&quot;">​</a></h1><p>Breeze is a TypeScript library for client applications that work with a lot of related data: applications where users search, view, add, change and delete records, and where the data forms a graph — customers with orders, orders with line items, line items with products.</p><p>Breeze keeps that data in a client-side cache of <strong>entities</strong>. You query a service, Breeze turns the JSON it gets back into entities, and from then on it tracks what you do to them. When you are ready, you send every change back in one request.</p><p>Breeze 3 does not depend on any UI framework. It works the same way in a React, Vue, Angular, Svelte or plain TypeScript application, and in Node. There are guides for <a href="/breeze-client-v3/guide/angular">Angular</a> and <a href="/breeze-client-v3/guide/react">React</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><h3 id="queries" tabindex="-1">Queries <a class="header-anchor" href="#queries" aria-label="Permalink to &quot;Queries&quot;">​</a></h3><ul><li>A fluent query API: <code>where</code>, <code>orderBy</code>, <code>skip</code>, <code>take</code>, <code>expand</code>, <code>select</code>.</li><li>Simple conditions (<code>freight &gt; 100</code>), compound conditions (<code>and</code>, <code>or</code>, <code>not</code>), functions (<code>toUpper</code>, <code>substring</code>, <code>length</code>, …), and conditions on related entities with <code>any</code> and <code>all</code>.</li><li><code>expand</code> brings related entities back in the same response.</li><li><code>select</code> projects a subset of properties, or flattens a graph.</li><li>Query results are merged into the cache. Entities you have changed but not saved keep your changes by default.</li><li>The same query object can run against the local cache instead of the server.</li></ul><p>See <a href="/breeze-client-v3/query/">Querying</a>.</p><h3 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h3><ul><li>Every entity a query returns, and every entity you create, goes into the cache of an <a href="/breeze-client-v3/api/classes/EntityManager"><code>EntityManager</code></a>.</li><li>Navigation properties connect cached entities to each other: <code>Customer</code> → <code>orders</code> → <code>orderDetails</code> → <code>product</code>, and back again.</li><li>You can use several managers side by side, for example to isolate an edit session from the main cache.</li><li>A cache can be exported to a string and imported again later, which is useful for offline scenarios.</li></ul><p>See <a href="/breeze-client-v3/guide/entitymanager-and-caching">EntityManager and caching</a> and <a href="/breeze-client-v3/guide/export-import">Export and import</a>.</p><h3 id="change-tracking" tabindex="-1">Change tracking <a class="header-anchor" href="#change-tracking" aria-label="Permalink to &quot;Change tracking&quot;">​</a></h3><ul><li>Each entity knows whether it is new, modified, marked for deletion or unchanged, and remembers its original values.</li><li>One call reverts an entity, or the whole cache, to its original values.</li><li>Events report property changes, state changes, and entities entering or leaving the cache.</li></ul><p>See <a href="/breeze-client-v3/guide/change-tracking">Change tracking</a> and <a href="/breeze-client-v3/guide/inside-the-entity">Inside the entity</a>.</p><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Validation rules come from metadata (required, maximum length, data type) and from validators you add yourself, at property or entity level.</li><li>Validation runs automatically, when you attach an entity, when you change a property and before you save. You can also run it on demand.</li><li>Validation messages are templates, so you can replace or localize them.</li></ul><p>See <a href="/breeze-client-v3/guide/validation">Validation</a>.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><ul><li><code>saveChanges()</code> sends every pending add, update and delete in one request, and the server applies them in one transaction.</li><li>One save can include entities of different types.</li><li>Keys generated by the server replace the client&#39;s temporary keys, and every foreign key that referred to them is updated.</li><li>Metadata marks the concurrency properties, so the server can detect optimistic concurrency conflicts.</li></ul><p>See <a href="/breeze-client-v3/guide/saving-changes">Saving changes</a>.</p><h3 id="metadata-driven-entities" tabindex="-1">Metadata-driven entities <a class="header-anchor" href="#metadata-driven-entities" aria-label="Permalink to &quot;Metadata-driven entities&quot;">​</a></h3><ul><li>Entity types, keys, relationships and validation rules are described by metadata. You can fetch the metadata from the server, write it by hand, or both.</li><li>Breeze builds entities from the metadata, so you do not have to write model classes. You can write them if you want to add behaviour.</li><li>Entities can have complex-type properties.</li></ul><p>See <a href="/breeze-client-v3/metadata/">Metadata</a> and <a href="/breeze-client-v3/guide/extending-entities">Extending entities</a>.</p><h2 id="what-it-talks-to" tabindex="-1">What it talks to <a class="header-anchor" href="#what-it-talks-to" aria-label="Permalink to &quot;What it talks to&quot;">​</a></h2><p>Out of the box, Breeze talks to a Breeze .NET server: ASP.NET Core with Entity Framework Core or NHibernate, using the <a href="https://github.com/Breeze/breeze-server-v3" target="_blank" rel="noreferrer">breeze-server-v3</a> packages. That server supplies the metadata, runs the queries and applies the saves.</p><p>The adapters are replaceable. To talk to a different backend, write a data service adapter — see <a href="/breeze-client-v3/server/">Talking to the server</a> and <a href="/breeze-client-v3/server/dataserviceadapter">DataServiceAdapter</a>. To route HTTP through your own code, supply a <code>fetch</code> function — see <a href="/breeze-client-v3/server/transport">Supplying your own transport</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/breeze-client-v3/guide/getting-started">Getting started</a> installs Breeze, configures it and runs a first query.</p>',28)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
